#!/usr/bin/env bash
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing cross-setting aggregate..."
decode "apply_aggregate.py" << 'B64EOF'

B64EOF
python apply_aggregate.py && rm apply_aggregate.py
echo "Installed. Re-run the primary evaluation to get the aggregate table."